        // Compute K * u_n first, then scale by dt^2 for better numerical accuracy
        Vector u_n_plus1 = 2.0 * u_n - u_minus1 - dt2 * (K * u_n);

        // Update for next iteration
        u_minus1 = u_n;
        u_n = u_n_plus1;

        // Store every 10th step (including step 100)
        if (step % 10 == 0) {
            output_points.push_back(u_n);
        }
    }

    // Output as JSON
    std::cout << "{\"test\":\"TRD1C\",\"timeseries\":[";

    for (size_t i = 0; i < output_points.size(); ++i) {
        if (i > 0) std::cout << ",";
        std::cout << "[";
        for (int j = 0; j < n; ++j) {
            if (j > 0) std::cout << ",";
            std::cout << std::scientific << std::setprecision(16) << output_points[i](j);
        }
        std::cout << "]";
    }

    std::cout << "]}" << std::endl;

    return 0;
}
